+\end{lemma}
+\begin{proof}
+	\leanok
+	\uses{lem:uniform-map-equal-fibers}
+	Every fiber of the first projection has cardinality $|B|$; apply
+	Lemma~\ref{lem:uniform-map-equal-fibers}.
+\end{proof}
